import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow that defines a run-once scheduled trigger at a specific date-time.

Flow(
    {
        $id: Now.ID['flow_trigger_scheduled_run_once'],
        name: 'Flow - Trigger Scheduled Run Once',
        description: 'Flow used by tests to validate run-once scheduled trigger configuration.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.scheduled.runOnce,
        { $id: Now.ID['trigger_scheduled_run_once'], annotation: 'Run-once scheduled trigger at a specific time' },
        {
            run_in: '2025-01-01 10:00:00',
        }
    ),
    () => {
        // Empty body; this test focuses on scheduled trigger configuration only
    }
)
